{
  "name": "{{name}}",
  "private": true,
  "scripts": {
    "build": "pnpm -r build",
    "test": "pnpm -r test",
    "typecheck": "pnpm -r typecheck",
    "changeset": "changeset",
    "release": "pnpm build && changeset publish"
  },
  "devDependencies": {
    "@changesets/cli": "latest",
    "tsup": "latest",
    "typescript": "~5.9.0",
    "vitest": "latest"
  }
}

/** Public API of @{{name}}/core: everything exported here is part of the contract. */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

import { expect, it } from "vitest";

import { greet } from "./index";

it("greets", () => {
  expect(greet("Ana")).toBe("Hello, Ana!");
});

import { greet } from "@{{name}}/core";

export function greetAll(names: string[]): string[] {
  return names.map(greet);
}

import { expect, it } from "vitest";

import { greetAll } from "./index";

it("greets everyone", () => {
  expect(greetAll(["Ana", "Luis"])).toEqual(["Hello, Ana!", "Hello, Luis!"]);
});
